import{_ as o,c as a,o as i,ae as t}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"UI 与移动端适配","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ui.md","filePath":"guide/ui.md","lastUpdated":1792605191000}'),l={name:"guide/ui.md"};function d(r,e,c,n,s,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="ui-与移动端适配" tabindex="-1">UI 与移动端适配 <a class="header-anchor" href="#ui-与移动端适配" aria-label="Permalink to &quot;UI 与移动端适配&quot;">​</a></h1><h2 id="ui-组件库" tabindex="-1">UI 组件库 <a class="header-anchor" href="#ui-组件库" aria-label="Permalink to &quot;UI 组件库&quot;">​</a></h2><p>模板同时接入 Vant、NutUI 和 Varlet，<code>unplugin-vue-components</code> 与 <code>unplugin-auto-import</code> 负责按需引入。示例页面用于比较三套组件库，不代表业务项目应长期混用。</p><p>开始正式项目时建议：</p><ol><li>选定一套主 UI 组件库。</li><li>删除 <code>package.json</code> 中不再使用的 UI 包和 resolver。</li><li>清理 <code>build/vite/plugins/component.ts</code>、<code>autoImport.ts</code> 与 <code>src/main.ts</code> 中对应配置。</li><li>删除 Demo 页面中其他组件库的示例，再运行 <code>pnpm check</code>。</li></ol><h2 id="viewport-适配" tabindex="-1">Viewport 适配 <a class="header-anchor" href="#viewport-适配" aria-label="Permalink to &quot;Viewport 适配&quot;">​</a></h2><p><code>postcss.config.mjs</code> 使用 <code>cnjm-postcss-px-to-viewport</code>：</p><ul><li>业务样式按 750px 设计稿转换。</li><li>Vant、NutUI 和 Varlet 的依赖样式按 375px 设计宽度转换。</li><li>小于或等于 1px 的值不转换，避免细边框被放大。</li><li>默认目标为 Android 8+、iOS 15+ 和 Chrome 80+。</li></ul><h2 id="安全区与滚动" tabindex="-1">安全区与滚动 <a class="header-anchor" href="#安全区与滚动" aria-label="Permalink to &quot;安全区与滚动&quot;">​</a></h2><ul><li>布局内容区使用 <code>100dvh</code>、独立纵向滚动和 <code>overscroll-behavior</code>。</li><li>Tabbar 使用组件库的底部安全区能力。</li><li>详情页固定购买栏通过 <code>env(safe-area-inset-bottom)</code> 预留空间。</li></ul><p>新增底部固定操作区时，需要同时给内容区补足底部 padding，避免内容被遮挡。</p>',11)])])}const m=o(l,[["render",d]]);export{h as __pageData,m as default};
